content:
:root {
  font-family: Inter, system-ui, Avenir, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  font-weight: 400;

  color-scheme: dark;
  color: rgba(255, 255, 255, 0.87);
  background-color: #121212;

  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  width: 100vw;
  height: 100vh;
  overflow: hidden;
  background-color: #0b0b0f;
}

.app-container {
  position: relative;
  width: 100vw;
  height: 100vh;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.canvas-wrapper {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
}

.canvas {
  display: block;
  width: 100%;
  height: 100%;
}

.controls {
  position: absolute;
  top: 20px;
  left: 20px;
  z-index: 10;
  background: rgba(18, 18, 26, 0.75);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 12px;
  padding: 16px;
  width: 300px;
  max-height: calc(100vh - 40px);
  overflow-y: auto;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  transition: opacity 0.3s ease;
}

.title {
  font-size: 1.1rem;
  font-weight: 600;
  margin-bottom: 14px;
  color: #fff;
  letter-spacing: -0.01em;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  padding-bottom: 8px;
}

.control-group {
  margin-bottom: 12px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.control-group label {
  font-size: 0.8rem;
  color: rgba(255, 255, 255, 0.7);
  display: flex;
  justify-content: space-between;
}

.control-group input[type="range"] {
  width: 100%;
  accent-color: #6366f1;
  cursor: pointer;
}

.control-group select {
  width: 100%;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.15);
  color: #fff;
  padding: 6px 8px;
  border-radius: 6px;
  font-size: 0.85rem;
  outline: none;
  cursor: pointer;
}

.control-group select option {
  background: #1a1a24;
  color: #fff;
}

.btn {
  background: linear-gradient(135deg, #6366f1 0%, #4f46e5 100%);
  color: white;
  border: none;
  padding: 8px 14px;
  border-radius: 6px;
  font-size: 0.85rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
  width: 100%;
  margin-top: 6px;
  box-shadow: 0 4px 12px rgba(99, 102, 241, 0.3);
}

.btn:hover {
  background: linear-gradient(135deg, #4f46e5 0%, #4338ca 100%);
  box-shadow: 0 6px 16px rgba(99, 102, 241, 0.4);
  transform: translateY(-1px);
}

.btn:active {
  transform: translateY(0);
}

@media (max-width: 600px) {
  .controls {
    top: auto;
    bottom: 20px;
    left: 10px;
    right: 10px;
    width: auto;
    max-height: 40vh;
  }
}

import { useEffect, useRef } from 'react';
import './index.css';

interface ParticleCanvasProps {
  particleCount: number;
  speed: number;
  particleSize: number;
  colorTheme: string;
  effectType: string;
}

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  size: number;
  color: string;
  alpha: number;
  life: number;
  maxLife: number;
}

export default function ParticleCanvas({
  particleCount,
  speed,
  particleSize,
  colorTheme,
  effectType,
}: ParticleCanvasProps) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrameId: number;
    let width = (canvas.width = window.innerWidth);
    let height = (canvas.height = window.innerHeight);

    const handleResize = () => {
      if (!canvas) return;
      width = canvas.width = window.innerWidth;
      height = canvas.height = window.innerHeight;
    };

    window.addEventListener('resize', handleResize);

    // Mouse / Touch position
    const mouse = {
      x: width / 2,
      y: height / 2,
      targetX: width / 2,
      targetY: height / 2,
      isDown: false,
    };

    const handleMouseMove = (e: MouseEvent) => {
      mouse.targetX = e.clientX;
      mouse.targetY = e.clientY;
    };

    const handleTouchMove = (e: TouchEvent) => {
      if (e.touches.length > 0) {
        mouse.targetX = e.touches[0].clientX;
        mouse.targetY = e.touches[0].clientY;
      }
    };

    const handleMouseDown = () => { mouse.isDown = true; };
    const handleMouseUp = () => { mouse.isDown = false; };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('touchmove', handleTouchMove);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);

    // Color generator
    const getColors = (theme: string, index: number, total: number) => {
      switch (theme) {
        case 'sunset':
          return `hsl(${15 + (index / total) * 40}, 90%, 60%)`;
        case 'matrix':
          return `hsl(120, 100%, ${40 + Math.random() * 20}%)`;
        case 'rainbow':
          return `hsl(${(index / total) * 360}, 80%, 60%)`;
        case 'neon':
        default:
          return `hsl(${220 + (index / total) * 60}, 100%, 65%)`;
      }
    };

    // Initialize particles
    let particles: Particle[] = [];
    const initParticles = () => {
      particles = [];
      for (let i = 0; i < particleCount; i++) {
        particles.push({
          x: Math.random() * width,
          y: Math.random() * height,
          vx: (Math.random() - 0.5) * speed,
          vy: (Math.random() - 0.5) * speed,
          size: Math.random() * particleSize + 1,
          color: getColors(colorTheme, i, particleCount),
          alpha: Math.random() * 0.8 + 0.2,
          life: 0,
          maxLife: Math.random() * 200 + 100,
        });
      }
    };

    initParticles();

    // Animation Loop
    const render = () => {
      // Smooth mouse follow
      mouse.x += (mouse.targetX - mouse.x) * 0.1;
      mouse.y += (mouse.targetY - mouse.y) * 0.1;

      ctx.fillStyle = 'rgba(11, 11, 15, 0.2)';
      ctx.fillRect(0, 0, width, height);

      // Re-initialize if particleCount changes
      if (particles.length !== particleCount) {
        initParticles();
      }

      particles.forEach((p, index) => {
        // Update velocity based on effect type
        if (effectType === 'follow') {
          const dx = mouse.x - p.x;
          const dy = mouse.y - p.y;
          const dist = Math.sqrt(dx * dx + dy * dy);
          if (dist > 1) {
            p.vx += (dx / dist) * (speed * 0.1);
            p.vy += (dy / dist) * (speed * 0.1);
          }
          p.vx *= 0.95;
          p.vy *= 0.95;
        } else if (effectType === 'explosion' && mouse.isDown) {
          const dx = p.x - mouse.x;
          const dy = p.y - mouse.y;
          const dist = Math.sqrt(dx * dx + dy * dy) || 1;
          p.vx += (dx / dist) * (speed * 0.5);
          p.vy += (dy / dist) * (speed * 0.5);
        } else if (effectType === 'matrix') {
          p.vx = 0;
          p.vy = speed * 1.5;
        }

        p.x += p.vx;
        p.y += p.vy;

        // Boundary checks
        if (p.x < 0) p.x = width;
        if (p.x > width) p.x = 0;
        if (p.y < 0) p.y = height;
        if (p.y > height) p.y = 0;

        // Draw particle
        ctx.save();
        ctx.globalAlpha = p.alpha;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size * (particleSize / 3), 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();

        // Draw connecting lines for nearby particles
        for (let j = index + 1; j < particles.length; j += 5) {
          const p2 = particles[j];
          const distX = p.x - p2.x;
          const distY = p.y - p2.y;
          const distance = Math.sqrt(distX * distX + distY * distY);

          if (distance < 80) {
            ctx.save();
            ctx.globalAlpha = (1 - distance / 80) * 0.15;
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 0.5;
            ctx.beginPath();
            ctx.moveTo(p.x, p.y);
            ctx.lineTo(p2.x, p2.y);
            ctx.stroke();
            ctx.restore();
          }
        }
      });

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    return () => {
      window.removeEventListener('resize', handleResize);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
      cancelAnimationFrame(animationFrameId);
    };
  }, [particleCount, speed, particleSize, colorTheme, effectType]);

  return (
    <div className="canvas-wrapper">
      <canvas ref={canvasRef} className="canvas" />
    </div>
  );
}

import { useState } from 'react';
import ParticleCanvas from './ParticleCanvas';
import './index.css';

export default function App() {
  const [particleCount, setParticleCount] = useState<number>(150);
  const [speed, setSpeed] = useState<number>(2);
  const [particleSize, setParticleSize] = useState<number>(3);
  const [colorTheme, setColorTheme] = useState<string>('neon');
  const [effectType, setEffectType] = useState<string>('follow');

  const handleReset = () => {
    setParticleCount(150);
    setSpeed(2);
    setParticleSize(3);
    setColorTheme('neon');
    setEffectType('follow');
  };

  return (
    <div className="app-container">
      <ParticleCanvas
        particleCount={particleCount}
        speed={speed}
        particleSize={particleSize}
        colorTheme={colorTheme}
        effectType={effectType}
      />

      <div className="controls">
        <h1 className="title">パーティクル設定</h1>

        <div className="control-group">
          <label>
            <span>パーティクル数</span>
            <span>{particleCount}</span>
          </label>
          <input
            type="range"
            min="50"
            max="400"
            step="10"
            value={particleCount}
            onChange={(e) => setParticleCount(Number(e.target.value))}
          />
        </div>

        <div className="control-group">
          <label>
            <span>速度</span>
            <span>{speed}</span>
          </label>
          <input
            type="range"
            min="0.5"
            max="8"
            step="0.5"
            value={speed}
            onChange={(e) => setSpeed(Number(e.target.value))}
          />
        </div>

        <div className="control-group">
          <label>
            <span>サイズ</span>
            <span>{particleSize}</span>
          </label>
          <input
            type="range"
            min="1"
            max="8"
            step="1"
            value={particleSize}
            onChange={(e) => setParticleSize(Number(e.target.value))}
          />
        </div>

        <div className="control-group">
          <label>カラーテーマ</label>
          <select
            value={colorTheme}
            onChange={(e) => setColorTheme(e.target.value)}
          >
            <option value="neon">ネオンブルー</option>
            <option value="sunset">サンセット</option>
            <option value="matrix">マトリックス</option>
            <option value="rainbow">レインボー</option>
          </select>
        </div>

        <div className="control-group">
          <label>エフェクトモード</label>
          <select
            value={effectType}
            onChange={(e) => setEffectType(e.target.value)}
          >
            <option value="follow">マウス追従</option>
            <option value="explosion">クリック爆発（長押し）</option>
            <option value="matrix">マトリックス雨</option>
          </select>
        </div>

        <button className="btn" onClick={handleReset}>
          設定をリセット
        </button>
      </div>
    </div>
  );
}
